    h.ok(json!({"Command": "CreateQueue", "QueueName": name}));
}

fn tag(h: &mut Harness, tags: Value) -> Value {
    h.run(json!({"Command": "TagQueue", "QueueName": "q", "Tags": tags}))
}

fn tags(h: &mut Harness) -> Value {
    h.ok(json!({"Command": "ListQueueTags", "QueueName": "q"}))["Tags"].clone()
}

#[test]
fn a_new_queue_has_no_tags() {
    let mut h = Harness::new();
    create(&mut h, "q");
    assert_eq!(tags(&mut h), json!({}));
}

#[test]
fn tag_sets_replaces_and_untag_removes() {
    let mut h = Harness::new();
    create(&mut h, "q");
    assert_eq!(tag(&mut h, json!({"a": "1", "b": ""})), json!({"ok": true}));
    assert_eq!(tag(&mut h, json!({"a": "2", "c": "3"})), json!({"ok": true}));
    assert_eq!(tags(&mut h), json!({"a": "2", "b": "", "c": "3"}));
    let r = h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a", "zzz"]}));
    assert_eq!(r, json!({"ok": true}));
    assert_eq!(tags(&mut h), json!({"b": "", "c": "3"}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {}}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": []}));
    assert_eq!(tags(&mut h), json!({"b": "", "c": "3"}));
}

#[test]
fn keys_are_case_sensitive() {
    let mut h = Harness::new();
    create(&mut h, "q");
    tag(&mut h, json!({"k": "lower", "K": "upper"}));
    assert_eq!(tags(&mut h), json!({"k": "lower", "K": "upper"}));
}

#[test]
fn invalid_tags_are_rejected_without_effect() {
    let mut h = Harness::new();
    create(&mut h, "q");
    let long_key = "k".repeat(129);
    let long_value = "v".repeat(257);
    let two_byte_values = "é".repeat(129);
    for bad in [
        json!({"ok": "1", "bad key": "1"}),
        json!({"": "1"}),
        json!({long_key: "1"}),
        json!({"ok": 1}),
        json!({"ok": null}),
        json!({"ok": long_value}),
        json!({"ok": two_byte_values}),
    ] {
        assert_eq!(tag(&mut h, bad.clone())["error"]["code"], "InvalidParameterValue", "{bad}");
    }
    assert_eq!(tags(&mut h), json!({}));
    tag(&mut h, json!({"k".repeat(128): "v".repeat(256), "e": "é".repeat(128)}));
    assert_eq!(tags(&mut h).as_object().unwrap().len(), 2);
}

#[test]
fn parameter_errors_follow_the_check_order() {
    let mut h = Harness::new();
    create(&mut h, "q");
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "TagQueue", "Tags": {}})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": []})), "InvalidParameterValue");
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {"a": 1}})), "InvalidParameterValue");
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {}})), "QueueDoesNotExist");
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": {}})), "InvalidParameterValue");
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": [1]})), "InvalidParameterValue");
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a b"]})), "InvalidParameterValue");
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "nope", "TagKeys": []})), "QueueDoesNotExist");
    assert_eq!(h.err(json!({"Command": "ListQueueTags"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "ListQueueTags", "QueueName": "nope"})), "QueueDoesNotExist");
}

#[test]
fn at_most_fifty_tags() {
    let mut h = Harness::new();
    create(&mut h, "q");
    let many = |range: std::ops::Range<u32>| -> Value {
        range.map(|i| (format!("k{i}"), json!("v"))).collect::<serde_json::Map<_, _>>().into()
    };
    assert_eq!(tag(&mut h, many(0..50))["ok"], true);
    assert_eq!(tag(&mut h, many(49..51))["error"]["code"], "LimitExceeded");
    assert_eq!(tags(&mut h).as_object().unwrap().len(), 50);
    // Replacing existing keys does not count as new tags.
    assert_eq!(tag(&mut h, many(0..50))["ok"], true);
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["k0"]}));
    assert_eq!(tag(&mut h, many(48..51))["error"]["code"], "LimitExceeded");
    assert_eq!(tag(&mut h, json!({"new": "x"}))["ok"], true);
}

#[test]
fn tags_are_not_attributes_and_survive_purge_but_not_delete() {
    let mut h = Harness::new();
    create(&mut h, "q");
    tag(&mut h, json!({"a": "1"}));
    let r = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert!(r["Attributes"].get("Tags").is_none());
    // CreateQueue rule 4 ignores tags.
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "PurgeQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h), json!({"a": "1"}));
    h.ok(json!({"Command": "DeleteQueue", "QueueName": "q"}));
    create(&mut h, "q");
    assert_eq!(tags(&mut h), json!({}));
}
